mapper.select:
select i.id as interaction_id, i.target_id, i.create_time, case i.target_type when '1' then 'post' when '2' then 'course' when '3' then 'shortVideo' end as target_type, case i.target_type when '1' then (select p.post_title from learning_post p where p.post_id = i.target_id) when '2' then (select c.course_name from learning_course c where c.course_id = i.target_id) when '3' then (select v.video_title from learning_short_video v where v.video_id = i.target_id) end as title, case i.target_type when '2' then (select c.cover_url from learning_course c where c.course_id = i.target_id) when '3' then (select v.cover_url from learning_short_video v where v.video_id = i.target_id) end as cover_url, case i.target_type when '1' then (select u.user_name from learning_post p join sys_user u on u.user_id = p.user_id where p.post_id = i.target_id) when '3' then (select u.user_name from learning_short_video v join sys_user u on u.user_id = v.user_id where v.video_id = i.target_id) end as author from learning_interaction i where i.user_id = #{userId} and i.type = #{actionType}
and i.target_type = #{targetType}
and (case i.target_type when '1' then (select count(*) from learning_post p where p.post_id = i.target_id and p.del_flag = '0' and p.status = '0') when '2' then (select count(*) from learning_course c where c.course_id = i.target_id and c.del_flag = '0' and c.status = '0') when '3' then (select count(*) from learning_short_video v where v.video_id = i.target_id and v.del_flag = '0' and v.status = '0') end) > 0 order by i.create_time desc, i.id desc
